        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ROOM_RENT_DIFFERENCE_CO_PAY_AMOUNT end) as ROOM_RENT_DIFFERENCE_CO_PAY_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ROOM_RENT_PER_DAY end) as ROOM_RENT_PER_DAY,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NEONATAL_CHARGES_AMOUNT end) as NEONATAL_CHARGES_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PATIENT_PAID_AMOUNT end) as PATIENT_PAID_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CO_PAY_TYPE end) as CO_PAY_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TOTAL_CLAIMED_AMOUNT end) as TOTAL_CLAIMED_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then APPROVED_PACKAGE_AMOUNT end) as APPROVED_PACKAGE_AMOUNT,
