        max(case when SOURCE_RUN = 'opus_health_v2' then FAMILY_PHYSICIAN_CONTACT_NUMBER end) as FAMILY_PHYSICIAN_CONTACT_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_v2' then TREATING_DOCTOR_CONTACT_NUMBER end) as TREATING_DOCTOR_CONTACT_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_v2' then CLINICAL_FINDINGS_DESCRIPTION end) as CLINICAL_FINDINGS_DESCRIPTION,
