        max(case when SOURCE_RUN = 'opus_health_v2' then DIAGNOSTIC_TEST_CONDUCTED_INDICATOR end) as DIAGNOSTIC_TEST_CONDUCTED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then DELIVERY_DATE end) as DELIVERY_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then LAST_MENSTRUAL_PERIOD_DATE end) as LAST_MENSTRUAL_PERIOD_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then HOSPITALISATION_TYPE end) as HOSPITALISATION_TYPE,
        max(case when SOURCE_RUN = 'opus_health_v2' then EXPECTED_LENGTH_OF_STAY_DAYS end) as EXPECTED_LENGTH_OF_STAY_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then ICU_STAY_DAYS end) as ICU_STAY_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then ROOM_STAY_DAYS end) as ROOM_STAY_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then LAST_CONSULTATION_DATE end) as LAST_CONSULTATION_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when PRESCRIPTION_REFERENCE is not null or PRESCRIPTION_DETAILS is not null or ROOM_RENT_ELIGIBILITY_PERCENTAGE is not null or ROOM_GRADE is not null or AVAILED_ROOM_RENT_PER_DAY is not null or DISEASE_CATEGORY is not null or PRIMARY_DIAGNOSIS_CLASSIFICATION is not null or MAJOR_DISEASE_CATEGORY is not null or NOT_COVERED_AMOUNT is not null or SUM_INSURED_EXHAUSTED_AMOUNT is not null or CORPORATE_BUFFER_UTILISED_AMOUNT is not null or PROVISIONAL_DIAGNOSIS is not null or CORPORATE_BUFFER_AMOUNT is not null or DOCTOR_CHARGES_AMOUNT is not null or PATHOLOGY_CHARGES_AMOUNT is not null or RADIOLOGY_CHARGES_AMOUNT is not null or CARDIOLOGY_CHARGES_AMOUNT is not null or EQUIPMENT_CHARGES_AMOUNT is not null or NON_MEDICAL_CHARGES_AMOUNT is not null or INSURED_DISALLOWED_AMOUNT is not null or INSURED_DISALLOWANCE_REASON is not null or SERVICE_CHARGES_AMOUNT is not null or ADMISSION_TYPE is not null or NON_NETWORK_CO_PAY_AMOUNT is not null or ROOM_RENT_DIFFERENCE_CO_PAY_AMOUNT is not null or ROOM_RENT_PER_DAY is not null or NEONATAL_CHARGES_AMOUNT is not null or PATIENT_PAID_AMOUNT is not null or CO_PAY_TYPE is not null or TOTAL_CLAIMED_AMOUNT is not null or APPROVED_PACKAGE_AMOUNT is not null or DIAGNOSIS_CODE is not null or DIAGNOSIS_DESCRIPTION is not null or PROCEDURE_CODE is not null or PROCEDURE_DESCRIPTION is not null or SPECIALIST_CHARGES is not null or CONSULTANT_CHARGES is not null or PHYSICIAN_FEES is not null or IMAGING_STUDIES_CHARGES is not null or NORMAL_ROOM_DAYS is not null or ICU_DAYS is not null or ELIGIBLE_ICU_RENT_AMOUNT is not null or ATTENDANT_NAME is not null or ATTENDANT_CONTACT_NUMBER is not null or CORPORATE_GROUP_REFERENCE is not null or OTHER_HEALTH_COVER_DECLARED_INDICATOR is not null or OTHER_INSURER_NAME is not null or OTHER_HEALTH_COVER_DETAIL is not null or FAMILY_PHYSICIAN_INDICATOR is not null or FAMILY_PHYSICIAN_NAME is not null or FAMILY_PHYSICIAN_CONTACT_NUMBER is not null or TREATING_DOCTOR_CONTACT_NUMBER is not null or CLINICAL_FINDINGS_DESCRIPTION is not null or AILMENT_DURATION_DAYS is not null or FIRST_CONSULTATION_DATE is not null or PROVISIONAL_DIAGNOSIS_DESCRIPTION is not null or INVESTIGATION_AND_MEDICAL_MANAGEMENT_DETAIL is not null or DRUG_ADMINISTRATION_DETAIL is not null or OTHER_TREATMENT_DETAIL is not null or ROAD_TRAFFIC_ACCIDENT_INDICATOR is not null or INJURY_CIRCUMSTANCE_DESCRIPTION is not null or POLICE_REPORT_INDICATOR is not null or INJURY_OR_DISEASE_INDICATOR is not null or DIAGNOSTIC_TEST_CONDUCTED_INDICATOR is not null or DELIVERY_DATE is not null or LAST_MENSTRUAL_PERIOD_DATE is not null or HOSPITALISATION_TYPE is not null or EXPECTED_LENGTH_OF_STAY_DAYS is not null or ICU_STAY_DAYS is not null or ROOM_STAY_DAYS is not null or LAST_CONSULTATION_DATE is not null
                     then md5(upper(coalesce(cast(PRESCRIPTION_REFERENCE as varchar), '') || '|' || coalesce(cast(PRESCRIPTION_DETAILS as varchar), '') || '|' || coalesce(cast(ROOM_RENT_ELIGIBILITY_PERCENTAGE as varchar), '') || '|' || coalesce(cast(ROOM_GRADE as varchar), '') || '|' || coalesce(cast(AVAILED_ROOM_RENT_PER_DAY as varchar), '') || '|' || coalesce(cast(DISEASE_CATEGORY as varchar), '') || '|' || coalesce(cast(PRIMARY_DIAGNOSIS_CLASSIFICATION as varchar), '') || '|' || coalesce(cast(MAJOR_DISEASE_CATEGORY as varchar), '') || '|' || coalesce(cast(NOT_COVERED_AMOUNT as varchar), '') || '|' || coalesce(cast(SUM_INSURED_EXHAUSTED_AMOUNT as varchar), '') || '|' || coalesce(cast(CORPORATE_BUFFER_UTILISED_AMOUNT as varchar), '') || '|' || coalesce(cast(PROVISIONAL_DIAGNOSIS as varchar), '') || '|' || coalesce(cast(CORPORATE_BUFFER_AMOUNT as varchar), '') || '|' || coalesce(cast(DOCTOR_CHARGES_AMOUNT as varchar), '') || '|' || coalesce(cast(PATHOLOGY_CHARGES_AMOUNT as varchar), '') || '|' || coalesce(cast(RADIOLOGY_CHARGES_AMOUNT as varchar), '') || '|' || coalesce(cast(CARDIOLOGY_CHARGES_AMOUNT as varchar), '') || '|' || coalesce(cast(EQUIPMENT_CHARGES_AMOUNT as varchar), '') || '|' || coalesce(cast(NON_MEDICAL_CHARGES_AMOUNT as varchar), '') || '|' || coalesce(cast(INSURED_DISALLOWED_AMOUNT as varchar), '') || '|' || coalesce(cast(INSURED_DISALLOWANCE_REASON as varchar), '') || '|' || coalesce(cast(SERVICE_CHARGES_AMOUNT as varchar), '') || '|' || coalesce(cast(ADMISSION_TYPE as varchar), '') || '|' || coalesce(cast(NON_NETWORK_CO_PAY_AMOUNT as varchar), '') || '|' || coalesce(cast(ROOM_RENT_DIFFERENCE_CO_PAY_AMOUNT as varchar), '') || '|' || coalesce(cast(ROOM_RENT_PER_DAY as varchar), '') || '|' || coalesce(cast(NEONATAL_CHARGES_AMOUNT as varchar), '') || '|' || coalesce(cast(PATIENT_PAID_AMOUNT as varchar), '') || '|' || coalesce(cast(CO_PAY_TYPE as varchar), '') || '|' || coalesce(cast(TOTAL_CLAIMED_AMOUNT as varchar), '') || '|' || coalesce(cast(APPROVED_PACKAGE_AMOUNT as varchar), '') || '|' || coalesce(cast(DIAGNOSIS_CODE as varchar), '') || '|' || coalesce(cast(DIAGNOSIS_DESCRIPTION as varchar), '') || '|' || coalesce(cast(PROCEDURE_CODE as varchar), '') || '|' || coalesce(cast(PROCEDURE_DESCRIPTION as varchar), '') || '|' || coalesce(cast(SPECIALIST_CHARGES as varchar), '') || '|' || coalesce(cast(CONSULTANT_CHARGES as varchar), '') || '|' || coalesce(cast(PHYSICIAN_FEES as varchar), '') || '|' || coalesce(cast(IMAGING_STUDIES_CHARGES as varchar), '') || '|' || coalesce(cast(NORMAL_ROOM_DAYS as varchar), '') || '|' || coalesce(cast(ICU_DAYS as varchar), '') || '|' || coalesce(cast(ELIGIBLE_ICU_RENT_AMOUNT as varchar), '') || '|' || coalesce(cast(ATTENDANT_NAME as varchar), '') || '|' || coalesce(cast(ATTENDANT_CONTACT_NUMBER as varchar), '') || '|' || coalesce(cast(CORPORATE_GROUP_REFERENCE as varchar), '') || '|' || coalesce(cast(OTHER_HEALTH_COVER_DECLARED_INDICATOR as varchar), '') || '|' || coalesce(cast(OTHER_INSURER_NAME as varchar), '') || '|' || coalesce(cast(OTHER_HEALTH_COVER_DETAIL as varchar), '') || '|' || coalesce(cast(FAMILY_PHYSICIAN_INDICATOR as varchar), '') || '|' || coalesce(cast(FAMILY_PHYSICIAN_NAME as varchar), '') || '|' || coalesce(cast(FAMILY_PHYSICIAN_CONTACT_NUMBER as varchar), '') || '|' || coalesce(cast(TREATING_DOCTOR_CONTACT_NUMBER as varchar), '') || '|' || coalesce(cast(CLINICAL_FINDINGS_DESCRIPTION as varchar), '') || '|' || coalesce(cast(AILMENT_DURATION_DAYS as varchar), '') || '|' || coalesce(cast(FIRST_CONSULTATION_DATE as varchar), '') || '|' || coalesce(cast(PROVISIONAL_DIAGNOSIS_DESCRIPTION as varchar), '') || '|' || coalesce(cast(INVESTIGATION_AND_MEDICAL_MANAGEMENT_DETAIL as varchar), '') || '|' || coalesce(cast(DRUG_ADMINISTRATION_DETAIL as varchar), '') || '|' || coalesce(cast(OTHER_TREATMENT_DETAIL as varchar), '') || '|' || coalesce(cast(ROAD_TRAFFIC_ACCIDENT_INDICATOR as varchar), '') || '|' || coalesce(cast(INJURY_CIRCUMSTANCE_DESCRIPTION as varchar), '') || '|' || coalesce(cast(POLICE_REPORT_INDICATOR as varchar), '') || '|' || coalesce(cast(INJURY_OR_DISEASE_INDICATOR as varchar), '') || '|' || coalesce(cast(DIAGNOSTIC_TEST_CONDUCTED_INDICATOR as varchar), '') || '|' || coalesce(cast(DELIVERY_DATE as varchar), '') || '|' || coalesce(cast(LAST_MENSTRUAL_PERIOD_DATE as varchar), '') || '|' || coalesce(cast(HOSPITALISATION_TYPE as varchar), '') || '|' || coalesce(cast(EXPECTED_LENGTH_OF_STAY_DAYS as varchar), '') || '|' || coalesce(cast(ICU_STAY_DAYS as varchar), '') || '|' || coalesce(cast(ROOM_STAY_DAYS as varchar), '') || '|' || coalesce(cast(LAST_CONSULTATION_DATE as varchar), '')))
                end as SAT_CLAIM_HEALTH_DETAIL_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_HEALTH_DETAIL_HASHDIFF is not null
